descriptor.run:
node -e '
  const fs = require("node:fs")
  const path = process.argv[1]
  if (!fs.existsSync(path)) {
    throw new Error("no vitest report at " + path + " — the lane produced no run at all.")
  }
  const report = JSON.parse(fs.readFileSync(path, "utf8"))
  const passed = report.numPassedTests ?? 0
  const skipped = report.numPendingTests ?? 0
  if (passed === 0 || skipped > 0) {
    throw new Error(
      "the workerd lane reported " + passed + " passed and " + skipped + " skipped. " +
        "This job is the only place DAWN_TEST_WORKERD=1 is set, so a skip here means the " +
        "merge gate ran nothing while still exiting 0. Check that the flag name in " +
        "packages/cli/test/workerd-lane.test.ts still matches the one this job exports.",
    )
  }
  console.log("workerd lane ran: " + passed + " passed, 0 skipped.")
' "${{ runner.temp }}/workerd-lane-report.json"

set -eu
case "$EVENT_NAME" in
  pull_request)
    REQUIRED="$(pnpm exec tsx scripts/kubernetes-compat/workflow.ts scope --event pull_request --base "$BASE_SHA" --head "$HEAD_SHA")"
    ;;
  schedule|workflow_dispatch)
    REQUIRED="$(pnpm exec tsx scripts/kubernetes-compat/workflow.ts scope --event "$EVENT_NAME")"
    ;;
  *)
    echo "Unsupported workflow event: $EVENT_NAME" >&2
    exit 1
    ;;
esac
case "$REQUIRED" in
  true|false) ;;
  *) echo "Malformed compatibility scope output" >&2; exit 1 ;;
esac
MATRIX="$(pnpm exec tsx scripts/kubernetes-compat/workflow.ts matrix)"
[ -n "$MATRIX" ] || { echo "Empty compatibility matrix output" >&2; exit 1; }
[ "$(printf '%s' "$MATRIX" | wc -l | tr -d ' ')" -eq 0 ] \
  || { echo "Compatibility matrix output must be compact" >&2; exit 1; }
printf 'required=%s\nmatrix=%s\n' "$REQUIRED" "$MATRIX" >> "$GITHUB_OUTPUT"
